//! Golden-corpus tests: the Rust port must agree with the Python oracle on
//! every case.
//!
//! The files under `tests/golden/` are generated by
//! `apps/server/tools/net/ssrf_corpus.py`, which runs the real
//! `plane/utils/ip_address.py`, `plane/utils/url_security.py` and
//! `WebhookSerializer._validate_webhook_url` from `apps/api` with a stubbed DNS
//! resolver. Each row carries the resolver's answer, the allow lists and every
//! expected verdict (URL split, `validate_url`, the pinning resolution, and the
//! webhook policy), so nothing here re-derives an expectation.
//!
//! Regenerate with the pinned interpreter and commit the result:
//!
//! ```sh
//! apps/api/.venv/bin/python apps/server/tools/net/ssrf_corpus.py
//! apps/api/.venv/bin/python apps/server/tools/net/ssrf_corpus.py --check
//! ```
//!
//! A failure means the port differs from Django, never that the golden file is
//! wrong: fix the port. The one exception is a Python version change (the corpus
//! records the interpreter that produced it), which is a deliberate
//! regeneration.

use std::collections::BTreeMap;
use std::net::IpAddr;

use plane_net::dns::StubResolver;
use plane_net::pyurl;
use plane_net::ssrf;
use plane_net::webhook;
use serde::Deserialize;

const URL_CORPUS: &str = include_str!("golden/ssrf_urls.jsonl");
const IP_CORPUS: &str = include_str!("golden/ssrf_ips.jsonl");

#[derive(Debug, Deserialize)]
struct UrlRow {
    id: String,
    url: String,
    dns: DnsSpec,
    allowed_ips: Vec<String>,
    allowed_hosts: Vec<String>,
    disallowed_domains: Vec<String>,
    request_host: String,
    #[serde(default)]
    tags: Vec<String>,
    expect: UrlExpect,
}

#[derive(Debug, Default, Deserialize)]
struct DnsSpec {
    #[serde(default)]
    hosts: BTreeMap<String, Vec<String>>,
    default: Option<Vec<String>>,
    #[serde(default)]
    error: bool,
}

#[derive(Debug, Deserialize)]
struct UrlExpect {
    split: Outcome<SplitOk>,
    validate: Outcome<()>,
    resolve: Outcome<ResolveOk>,
    webhook: Outcome<()>,
}

#[derive(Debug, Deserialize)]
#[serde(untagged)]
enum Outcome<T> {
    Ok {
        ok: T,
    },
    Err {
        error: String,
        #[serde(default)]
        error_type: String,
    },
}

#[derive(Debug, Deserialize, PartialEq, Eq)]
struct SplitOk {
    scheme: String,
    hostname: String,
    port: u16,
    path: String,
    auth: Option<Vec<String>>,
}

#[derive(Debug, Deserialize, PartialEq, Eq)]
struct ResolveOk {
    ips: Vec<String>,
    trusted: bool,
    host_header: String,
}

fn parse_addresses(addresses: &[String]) -> Vec<IpAddr> {
    addresses
        .iter()
        .map(|address| address.parse().expect("corpus addresses are canonical"))
        .collect()
}

fn resolver_for(spec: &DnsSpec) -> StubResolver {
    let mut resolver = if let Some(default) = &spec.default {
        StubResolver::new(BTreeMap::new(), Some(parse_addresses(default)))
    } else {
        StubResolver::new(BTreeMap::new(), None)
    };
    if spec.error {
        resolver = StubResolver::failing();
    }
    for (host, addresses) in &spec.hosts {
        resolver = resolver.with_host(host, parse_addresses(addresses));
    }
    resolver
}

fn policy_for(row: &UrlRow) -> ssrf::SsrfPolicy {
    let (networks, warnings) = ssrf::SsrfPolicy::parse_cidr_list(&row.allowed_ips.join(", "));
    assert!(
        warnings.is_empty(),
        "{}: unroutable allow-list entry in corpus: {warnings:?}",
        row.id
    );
    ssrf::SsrfPolicy::new(networks, row.allowed_hosts.clone())
}

fn expect_ok<T>(outcome: &Outcome<T>) -> Option<&T> {
    match outcome {
        Outcome::Ok { ok } => Some(ok),
        Outcome::Err { .. } => None,
    }
}

fn expect_err<T>(outcome: &Outcome<T>) -> Option<(&str, &str)> {
    match outcome {
        Outcome::Err { error, error_type } => Some((error.as_str(), error_type.as_str())),
        Outcome::Ok { .. } => None,
    }
}

fn rows() -> Vec<UrlRow> {
    URL_CORPUS
        .lines()
        .filter(|line| !line.is_empty())
        .map(|line| serde_json::from_str(line).expect("corpus line is valid JSON"))
        .collect()
}

#[test]
fn url_corpus_agrees_with_python() {
    let rows = rows();
    assert!(
        rows.len() >= 2_000,
        "the corpus must stay at or above the 2,000-input floor, found {}",
        rows.len()
    );

    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let mut counts = (0usize, 0usize);

    for row in &rows {
        let resolver = resolver_for(&row.dns);
        let policy = policy_for(row);
        let context = format!("{} ({:?}) {:?}", row.id, row.tags, row.url);

        // 1. `_split_target`.
        let split = pyurl::split_target(&row.url);
        match (expect_ok(&row.expect.split), expect_err(&row.expect.split)) {
            (Some(expected), None) => {
                let actual =
                    split.unwrap_or_else(|error| panic!("{context}: split failed: {error}"));
                let actual = SplitOk {
                    scheme: actual.scheme,
                    hostname: actual.hostname,
                    port: actual.port,
                    path: actual.path,
                    auth: actual.auth.map(|(user, pass)| vec![user, pass]),
                };
                assert_eq!(&actual, expected, "{context}: split differs");
                counts.0 += 1;
            }
            (None, Some((expected, expected_type))) => {
                let error = split.expect_err(&format!("{context}: split should fail"));
                assert_eq!(error.message(), expected, "{context}: split error differs");
                assert_eq!(expected_type, "ValueError", "{context}: split error type");
                counts.1 += 1;
            }
            _ => panic!("{context}: malformed split expectation"),
        }

        // 2. `validate_url` (create/update time).
        let validate = runtime.block_on(ssrf::validate_url(&resolver, &row.url, &policy));
        match (
            expect_ok(&row.expect.validate),
            expect_err(&row.expect.validate),
        ) {
            (Some(()), None) => {
                if let Err(error) = &validate {
                    panic!("{context}: validate should accept: {error}");
                }
            }
            (None, Some((expected, expected_type))) => {
                let error = validate.expect_err(&format!("{context}: validate should fail"));
                assert_eq!(
                    error.message(),
                    expected,
                    "{context}: validate error differs"
                );
                assert_eq!(
                    expected_type, "ValueError",
                    "{context}: validate error type"
                );
            }
            _ => panic!("{context}: malformed validate expectation"),
        }

        // 3. The pinning path: `_fetch_validated_hop`'s resolution plus the
        // `Host` header `_request_to_ip` would send.
        let hop = runtime.block_on(ssrf::validate_hop(&resolver, &row.url, &policy));
        match (
            expect_ok(&row.expect.resolve),
            expect_err(&row.expect.resolve),
        ) {
            (Some(expected), None) => {
                let hop = hop.unwrap_or_else(|error| panic!("{context}: hop failed: {error}"));
                let actual = ResolveOk {
                    ips: hop
                        .addresses
                        .iter()
                        .map(std::string::ToString::to_string)
                        .collect(),
                    trusted: hop.trusted,
                    host_header: hop.target.host_header(),
                };
                assert_eq!(&actual, expected, "{context}: pinning differs");
            }
            (None, Some((expected, expected_type))) => {
                let error = hop.expect_err(&format!("{context}: hop should fail"));
                assert_eq!(error.message(), expected, "{context}: hop error differs");
                assert_eq!(expected_type, "ValueError", "{context}: hop error type");
            }
            _ => panic!("{context}: malformed resolve expectation"),
        }

        // 4. The webhook serializer's create/update guard.
        let webhook = runtime.block_on(webhook::validate_webhook_url(
            &resolver,
            &row.url,
            &policy,
            &row.disallowed_domains,
            Some(&row.request_host),
        ));
        match (
            expect_ok(&row.expect.webhook),
            expect_err(&row.expect.webhook),
        ) {
            (Some(()), None) => {
                if let Err(error) = &webhook {
                    panic!("{context}: webhook should accept: {error}");
                }
            }
            (None, Some((expected, expected_type))) => {
                let error = webhook.expect_err(&format!("{context}: webhook should fail"));
                assert_eq!(
                    error.message(),
                    expected,
                    "{context}: webhook error differs"
                );
                assert_eq!(
                    expected_type, "ValidationError",
                    "{context}: webhook error type"
                );
            }
            _ => panic!("{context}: malformed webhook expectation"),
        }
    }

    // Both halves of every branch must be exercised, or the corpus stopped
    // testing something.
    assert!(counts.0 > 1_500, "split successes: {}", counts.0);
    assert!(counts.1 > 100, "split errors: {}", counts.1);
    eprintln!("url corpus: {} cases", rows.len());
}

#[derive(Debug, Deserialize)]
struct IpRow {
    id: String,
    input: String,
    expect: Outcome<IpOk>,
}

#[derive(Debug, Deserialize)]
struct IpOk {
    canonical: String,
    version: u8,
    is_blocked: bool,
    is_private: bool,
    is_loopback: bool,
    is_reserved: bool,
    is_link_local: bool,
    is_multicast: bool,
    is_unspecified: bool,
}

#[test]
fn ip_corpus_agrees_with_python() {
    let rows: Vec<IpRow> = IP_CORPUS
        .lines()
        .filter(|line| !line.is_empty())
        .map(|line| serde_json::from_str(line).expect("corpus line is valid JSON"))
        .collect();
    assert!(rows.len() >= 6_000, "ip corpus shrank to {}", rows.len());

    let mut blocked = 0usize;
    let mut allowed = 0usize;
    for row in &rows {
        let parsed = plane_net::ipaddr::parse_python_ip(&row.input);
        match (&row.expect, parsed) {
            (Outcome::Err { error, .. }, None) => {
                let expected = format!(
                    "{} does not appear to be an IPv4 or IPv6 address",
                    pyurl::repr_str(&row.input)
                );
                assert_eq!(&expected, error, "{}: ip parse error differs", row.id);
            }
            (Outcome::Ok { ok }, Some(parsed)) => {
                // `IpAddr` cannot carry an IPv6 zone; Python's canonical form
                // does, and the validator strips it before classifying.
                let canonical = parsed.to_string();
                let expected_canonical = ok.canonical.split('%').next().unwrap_or("");
                assert_eq!(canonical, expected_canonical, "{}: canonical form", row.id);
                let version = if parsed.is_ipv4() { 4 } else { 6 };
                assert_eq!(version, ok.version, "{}: version", row.id);
                assert_eq!(
                    plane_net::is_blocked_ip(parsed),
                    ok.is_blocked,
                    "{}: is_blocked({})",
                    row.id,
                    row.input
                );
                let properties = plane_net::properties(parsed);
                assert_eq!(
                    properties.is_private, ok.is_private,
                    "{}: is_private",
                    row.id
                );
                assert_eq!(
                    properties.is_loopback, ok.is_loopback,
                    "{}: is_loopback",
                    row.id
                );
                assert_eq!(
                    properties.is_reserved, ok.is_reserved,
                    "{}: is_reserved",
                    row.id
                );
                assert_eq!(
                    properties.is_link_local, ok.is_link_local,
                    "{}: is_link_local",
                    row.id
                );
                assert_eq!(
                    properties.is_multicast, ok.is_multicast,
                    "{}: is_multicast",
                    row.id
                );
                assert_eq!(
                    properties.is_unspecified, ok.is_unspecified,
                    "{}: is_unspecified",
                    row.id
                );
                if ok.is_blocked {
                    blocked += 1;
                } else {
                    allowed += 1;
                }
            }
            (expected, actual) => panic!(
                "{}: parse disagreement for {:?}: expected {:?}, got {actual:?}",
                row.id, row.input, expected
            ),
        }
    }
    assert!(blocked > 500, "blocked samples: {blocked}");
    assert!(allowed > 100, "allowed samples: {allowed}");
    eprintln!("ip corpus: {} cases", rows.len());
}
